input.oldString:
function draw() {
    ctx.clearRect(0, 0, W, H);
    // Draw ship
    ctx.fillStyle = ship.alive ? '#0ff' : '#f00';
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();
    // Vacuum beam visual
    if (vacuumOn) {
      ctx.strokeStyle = '#0ff';
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(ship.x + ship.w / 2, ship.y);
      ctx.lineTo(ship.x + ship.w / 2, 0);
      ctx.stroke();
    }
    // Draw objects
    objects.forEach(o => {
      ctx.fillStyle = o.debris ? '#ff0' : '#888';
      ctx.fillRect(o.x, o.y, o.w, o.h);
    });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + ship.cargo, 10, 20);
    if (!ship.alive) ctx.fillText('GAME OVER', W / 2 - 50, H / 2);
  }

input.newString:
function draw() {
    // Background gradient
    const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
    bgGrad.addColorStop(0, '#001');
    bgGrad.addColorStop(1, '#003');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, W, H);

    // Draw ship – triangle
    ctx.fillStyle = ship.alive ? '#0ff' : '#f00';
    ctx.beginPath();
    ctx.moveTo(ship.x + ship.w / 2, ship.y);
    ctx.lineTo(ship.x, ship.y + ship.h);
    ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
    ctx.closePath();
    ctx.fill();

    // Vacuum beam visual – glowing gradient
    if (vacuumOn) {
      const beamGrad = ctx.createLinearGradient(0, ship.y, 0, 0);
      beamGrad.addColorStop(0, 'rgba(0,255,255,0)');
      beamGrad.addColorStop(1, 'rgba(0,255,255,0.4)');
      ctx.fillStyle = beamGrad;
      ctx.fillRect(ship.x + ship.w / 2 - 2, 0, 4, ship.y);
    }

    // Helper to draw a star for debris
    function drawStar(cx, cy, spikes, outerR, innerR, color) {
      let rot = Math.PI / 2 * 3;
      let x = cx;
      let y = cy;
      const step = Math.PI / spikes;
      ctx.beginPath();
      ctx.moveTo(cx, cy - outerR);
      for (let i = 0; i < spikes; i++) {
        x = cx + Math.cos(rot) * outerR;
        y = cy + Math.sin(rot) * outerR;
        ctx.lineTo(x, y);
        rot += step;

        x = cx + Math.cos(rot) * innerR;
        y = cy + Math.sin(rot) * innerR;
        ctx.lineTo(x, y);
        rot += step;
      }
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();
    }

    // Draw objects with better visuals
    objects.forEach(o => {
      if (o.debris) {
        drawStar(o.x + o.w / 2, o.y + o.h / 2, 5, o.w / 2, o.w / 4, '#ff0');
      } else {
        // asteroid as gray circle with slight radial gradient
        const grad = ctx.createRadialGradient(
          o.x + o.w / 2,
          o.y + o.h / 2,
          o.w * 0.1,
          o.x + o.w / 2,
          o.y + o.h / 2,
          o.w / 2
        );
        grad.addColorStop(0, '#555');
        grad.addColorStop(1, '#222');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(o.x + o.w / 2, o.y + o.h / 2, o.w / 2, 0, Math.PI * 2);
        ctx.fill();
      }
    });

    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + ship.cargo, 10, 20);
    if (!ship.alive) ctx.fillText('GAME OVER', W / 2 - 50, H / 2);
  }

